mapper.select:
select
IFNULL(SUM(quantity),0) as quantity,
IFNULL(SUM(mete),0) as mete,
IFNULL(SUM(total_area),0) as total_area
FROM project_receiving_summary
where bool_delete_enum = 0
and project_id = #{projectId}
and product_type = #{productType}

    and monomer_id = #{monomerId}


    and area_id = #{areaId}


    and category = #{category}

SELECT a.id product_id, #{productType} product_type, a.name ,
a.serial_number,
a.specification,
a.quantity, IFNULL(rs.quantity,0) AS receiving_quantity, (CASE IFNULL(rs.quantity,0) WHEN 0 THEN 1 WHEN a.quantity THEN 4 ELSE 2 END) AS receiving_status
FROM tech_artifact AS a
FROM tech_enclosure AS a
FROM tech_standard_part AS a
FROM tech_machine_part AS a
LEFT JOIN project_receiving_summary AS rs ON a.id = rs.product_id AND rs.product_type & #{productType} > 0 AND rs.bool_delete_enum = 0 WHERE a.bool_delete_enum = 0
AND ( CASE IFNULL( rs.quantity, 0 ) WHEN 0 THEN 1 WHEN a.quantity THEN 4 ELSE 2 END ) = #{receivingStatus}
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.category = #{category}
AND a.area_id = #{areaId}
AND a.enclosure_plan_id = #{areaId}
ORDER BY a.id ASC

SELECT prs.*, prs.monomer_id as 'monomer.id', m.name as 'monomer.name', prs.area_id as 'area.id', (case prs.product_type when 4 then ep.name else a.name end ) as 'area.name', prs.quantity as receiving_quantity,
( select IFNULL(SUM(report_quantity),0) from project_install_report where bool_delete_enum = 0 and product_id = prs.product_id and product_type = prs.product_type and audit_status = 1) un_audit_quantity
from project_receiving_summary as prs left join plan_monomer m on m.id = prs.monomer_id and prs.product_type != 4 and m.bool_delete_enum = 0 left join plan_area a on a.id = prs.area_id and prs.product_type != 4 and a.bool_delete_enum = 0 left join enclosure_plan ep on ep.id = prs.area_id and prs.product_type = 4 and ep.bool_delete_enum = 0
where prs.bool_delete_enum = 0
AND prs.product_type = #{productType}
AND prs.project_id = #{projectId}
AND prs.monomer_id = #{monomerId}
AND prs.category = #{category}
AND prs.area_id = #{areaId}
AND prs.name like concat('%',#{name},'%')
AND prs.serial_number like concat('%',#{serialNumber},'%')
ORDER BY prs.product_id

SELECT prs.project_id, prs.project_type, prs.product_id, prs.product_type, prs.category, prs.name, prs.serial_number, prs.material, prs.specification, prs.length, prs.width, prs.net_weight, cp.id as 'project.id', cp.`name` as 'project.name', cp.project_type as 'project.projectType', cp.`serial_number` as 'project.serial_number', prs.monomer_id as 'monomer.id', m.name as 'monomer.name', prs.area_id as 'area.id', a.name as 'area.name', prs.quantity as quantity, prs.quantity as receiving_quantity, report.un_audit_quantity, prs.quantity - IFNULL(prs.install_quantity,0) - IFNULL(report.un_audit_quantity,0) as canInstallQuantity, CASE WHEN prs.product_type = 2 THEN prs.net_weight * (prs.quantity - IFNULL(prs.install_quantity,0) - IFNULL(report.un_audit_quantity,0)) WHEN prs.product_type = 4 THEN prs.length / 1000 * (prs.quantity - IFNULL(prs.install_quantity,0) - IFNULL(report.un_audit_quantity,0)) ELSE 0 END AS mete from project_receiving_summary as prs left join ( select product_id,sum(report_quantity) as un_audit_quantity from project_install_report where bool_delete_enum = 0 and product_type = #{productType} and audit_status = ${@com.hzchum.scim.project.core.api.enums.AuditStatusEnum@AUDITING.getType()} group by product_id )report on report.product_id = prs.product_id LEFT JOIN contract_project cp ON cp.id = prs.project_id and cp.bool_delete_enum = 0 left join plan_monomer m on m.id = prs.monomer_id and prs.product_type != 4 and m.bool_delete_enum = 0 left join plan_area a on a.id = prs.area_id and prs.product_type != 4 and a.bool_delete_enum = 0 where prs.bool_delete_enum = 0 and prs.quantity - IFNULL(prs.install_quantity,0) - IFNULL(report.un_audit_quantity,0) > 0
AND prs.product_type = #{productType}
AND prs.project_id = #{projectId}
AND prs.monomer_id = #{monomerId}
AND prs.area_id = #{areaId}
and prs.area_id in
#{areaId}
AND prs.name like concat('%',#{name},'%')
AND prs.serial_number like concat('%',#{serialNumber},'%')
ORDER BY prs.product_id

SELECT prs.project_id, opl.supplier_id, prs.project_type, prs.product_id, prs.product_type, prs.category, prs.name, prs.serial_number, prs.material, prs.specification, prs.length, prs.width, prs.net_weight, cp.id as 'project.id', cp.`name` as 'project.name', cp.project_type as 'project.projectType', cp.`serial_number` as 'project.serial_number', prs.monomer_id as 'monomer.id', m.name as 'monomer.name', prs.area_id as 'area.id', a.name as 'area.name', opl.quantity as quantity, prs.quantity as receiving_quantity, opl.install_quantity as installQuantity, report.un_audit_quantity, LEAST(prs.quantity, IFNULL(opl.quantity,0)) - IFNULL(prs.install_quantity,0) - IFNULL(report.un_audit_quantity,0) as canInstallQuantity, CASE WHEN prs.product_type = 2 THEN opl.net_weight * (LEAST(prs.quantity, IFNULL(opl.quantity,0)) - IFNULL(prs.install_quantity,0) - IFNULL(report.un_audit_quantity,0)) WHEN prs.product_type = 4 THEN opl.length / 1000 * (LEAST(prs.quantity, IFNULL(opl.quantity,0)) - IFNULL(prs.install_quantity,0) - IFNULL(report.un_audit_quantity,0)) ELSE 0 END AS mete from project_receiving_summary as prs left join ( select product_id,sum(report_quantity) as un_audit_quantity from project_install_report where bool_delete_enum = 0 and product_type = #{productType} and audit_status = ${@com.hzchum.scim.project.core.api.enums.AuditStatusEnum@AUDITING.getType()} group by product_id )report on report.product_id = prs.product_id inner join ( select product_id, supplier_id, net_weight, length, surface_area, quantity, actual_quantity as install_quantity , accounting_unit from project_labor_subsupplier_order_product_link where bool_delete_enum = 0 and project_id = #{projectId} and product_type = #{productType}
and supplier_id = #{supplierId}
)opl on opl.product_id = prs.product_id LEFT JOIN contract_project cp ON cp.id = prs.project_id and cp.bool_delete_enum = 0 left join plan_monomer m on m.id = prs.monomer_id and m.bool_delete_enum = 0 left join plan_area a on a.id = prs.area_id and a.bool_delete_enum = 0 where prs.bool_delete_enum = 0 and LEAST(prs.quantity, opl.quantity) - IFNULL(prs.install_quantity,0) - IFNULL(report.un_audit_quantity,0) > 0
AND prs.product_type = #{productType}
AND prs.project_id = #{projectId}
AND prs.monomer_id = #{monomerId}
AND prs.category = #{category}
AND prs.area_id = #{areaId}
AND prs.name like concat('%',#{name},'%')
AND prs.serial_number like concat('%',#{serialNumber},'%')
ORDER BY prs.product_id
